import {canonicalizeAudioTaskIds, isAudioTaskId} from "@/lib/audioGeneration/taskIds";
import {z} from "zod";
import {MUSIC_DURATION_LIMITS} from "@/domain/music";
import type {ApimartCredentials, ApimartFailure, ApimartRequestOptions, ApimartResult} from "./apimart";
import {normalizeBaseUrl} from "./openaiCompatible";
import {redactCredentials} from "./safeError";

export const SPEECH_VOICES = ["alloy", "echo", "fable", "onyx", "nova", "shimmer"] as const;
const unicode = (max: number) => z.string().refine(value => [...value].length <= max, `最多 ${max} 个字符`);
export const speechInputSchema = z.object({
    model: z.literal("gpt-4o-mini-tts"), input: unicode(4096).refine(value => !!value.trim(), "请输入配音文字"),
    voice: z.enum(SPEECH_VOICES), response_format: z.enum(["wav", "opus", "aac", "flac", "pcm"]),
    speed: z.number().finite().min(.25).max(4).optional(),
}).strict();
export const flowMusicInputSchema = z.object({
    model: z.literal("flowmusic"),
    sound_prompt: z.string().optional(),
    lyrics: z.string().optional(),
    title: z.string().optional(),
    bpm: z.string().refine(value => value.trim() !== "" && Number.isFinite(Number(value)) && Number(value) >= 1, "BPM 必须至少为 1").optional(),
    length: z.number().int("音乐时长必须为整数秒").min(MUSIC_DURATION_LIMITS.flowmusic.min).max(MUSIC_DURATION_LIMITS.flowmusic.max).optional(),
    seed: z.string().optional(),
}).strict().refine(value => !!(value.sound_prompt?.trim() || value.lyrics?.trim()), "请填写风格描述或歌词");
export const sunoMusicInputSchema = z.object({
    model: z.literal("suno"),
    version: z.enum(["v6", "v6-wild", "v6-mini"]),
    custom: z.boolean(),
    instrumental: z.boolean(),
    prompt: unicode(5000).optional(),
    title: unicode(80).optional(),
    style: unicode(1000).optional(),
    negative_tags: z.string().optional(),
    auto_lyrics: z.boolean().optional(),
    vocal_gender: z.enum(["Male", "Female"]).optional(),
    style_weight: z.number().finite().min(0).max(1).optional(),
    weirdness_constraint: z.number().finite().min(0).max(1).optional(),
    audio_weight: z.number().finite().min(0).max(1).optional(),
    variety: z.enum(["off", "normal", "high", "extra", "max"]).optional(),
    max_mode: z.boolean().optional(),
    audio_format: z.enum(["mp3", "m4a", "wav"]).optional(),
    duration: z.number().int("音乐时长必须为整数秒").min(MUSIC_DURATION_LIMITS.suno.min).max(MUSIC_DURATION_LIMITS.suno.max).optional(),
}).strict().superRefine((value, ctx) => {
    const issue = (message: string) => ctx.addIssue({code: "custom", message});
    if ((!value.custom || !value.instrumental) && !value.prompt?.trim()) issue("请填写创作描述或歌词");
    if (!value.custom && [...(value.prompt ?? "")].length > 3000) issue("灵感描述最多 3000 个字符");
    if (!value.custom && [value.title, value.style, value.negative_tags, value.auto_lyrics, value.duration, value.max_mode].some(field => field !== undefined)) issue("标题、风格、歌词调整、时长和 Max 模式仅适用于自定义模式");
});
export type SpeechInput = z.infer<typeof speechInputSchema>;
export type FlowMusicInput = z.infer<typeof flowMusicInputSchema>;
export type SunoMusicInput = z.infer<typeof sunoMusicInputSchema>;
export type MusicInput = FlowMusicInput | SunoMusicInput;
export const musicInputSchema = z.union([flowMusicInputSchema, sunoMusicInputSchema]);

export interface MusicResultTrack {
    /** Provider array position, one-based; never derive from a sorted/filtered list. */
    audioIndex: number;
    clipId?: string;
    audioId?: string;
    title: string;
    lyrics?: string;
    duration?: number;
    audioUrl: string;
    wavUrl?: string;
    imageUrl?: string;
}

export interface MusicTask {
    id: string;
    status: "pending" | "processing" | "completed" | "failed" | "unknown";
    providerStatus: string;
    progress?: number;
    tracks: MusicResultTrack[];
    cost?: number;
    creditsCost?: number;
    error?: string;
}

const record = (v: unknown): v is Record<string, unknown> => !!v && typeof v === "object" && !Array.isArray(v);
const finite = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const nonempty = (v: unknown): v is string => typeof v === "string" && !!v.trim();

function safeUrl(v: unknown): v is string {
    if (!nonempty(v)) return false;
    try {
        const u = new URL(v);
        return ["https:", "http:"].includes(u.protocol) && !u.username && !u.password;
    } catch {
        return false;
    }
}

const failure = (kind: ApimartFailure["kind"], message: string): ApimartFailure => ({ok: false, kind, message});
const aborted = (error: unknown, signal?: AbortSignal) => signal?.aborted || (error instanceof Error || error instanceof DOMException) && error.name === "AbortError";
const protocol = () => failure("protocol", "APIMart 音频响应不符合接口约定；请保留任务记录，不要自动重复提交");

async function audioRequest(credentials: ApimartCredentials, path: string, input: SpeechInput | MusicInput | undefined, options: ApimartRequestOptions): Promise<ApimartResult<{
    response: Response
}>> {
    const base = normalizeBaseUrl(credentials.baseUrl), key = credentials.apiKey.trim();
    if (!key || !safeUrl(base) || new URL(base).search || new URL(base).hash) return failure("validation", "请配置有效的 APIMart 地址和 API Key");
    if (options.signal?.aborted) return failure("aborted", "请求已停止；远端生成不会因此取消");
    try {
        const response = await (options.fetchImpl ?? fetch)(`${base}${path}`, {
            method: input ? "POST" : "GET",
            headers: {Authorization: `Bearer ${key}`, ...(input ? {"Content-Type": "application/json"} : {})},
            ...(input ? {body: JSON.stringify(input)} : {}),
            signal: options.signal,
            credentials: "omit",
            redirect: "error",
        });
        if (!response.ok) {
            let body: unknown;
            try {
                body = await response.json();
            } catch (error) {
                if (aborted(error, options.signal)) return failure("aborted", "请求已停止；远端生成不会因此取消");
                /* HTTP status remains authoritative for other body failures. */
            }
            const error = record(body) && record(body.error) ? body.error : undefined;
            const detail = typeof error?.message === "string" ? redactCredentials(error.message, key).slice(0, 300) : "请检查连接权限、余额和请求参数";
            return {
                ok: false,
                kind: "http",
                httpStatus: response.status,
                message: `APIMart 请求失败（${response.status}）：${detail}`
            };
        }
        return {ok: true, response};
    } catch (error) {
        return failure(aborted(error, options.signal) ? "aborted" : "network", "音频请求未能完成；提交结果可能尚未确认，请勿自动重复生成");
    }
}

async function jsonEnvelope(credentials: ApimartCredentials, path: string, input: MusicInput | undefined, options: ApimartRequestOptions): Promise<ApimartResult<{
    data: unknown
}>> {
    const result = await audioRequest(credentials, path, input, options);
    if (!result.ok) return result;
    let body: unknown;
    try {
        body = await result.response.json();
    } catch (error) {
        if (aborted(error, options.signal)) return failure("aborted", "请求已停止；远端生成不会因此取消");
        return protocol();
    }
    if (!record(body)) return protocol();
    if (body.error != null || body.success === false || (body.code !== undefined && body.code !== 200)) {
        const message = record(body.error) ? body.error.message : body.message;
        return failure("provider", typeof message === "string" ? redactCredentials(message, credentials.apiKey).slice(0, 300) : "APIMart 音频任务失败");
    }
    return body.code === 200 ? {ok: true, data: body.data} : protocol();
}

export async function generateApimartSpeech(credentials: ApimartCredentials, input: SpeechInput, options: ApimartRequestOptions = {}): Promise<ApimartResult<{
    blob: Blob
}>> {
    const parsed = speechInputSchema.safeParse(input);
    if (!parsed.success) return failure("validation", parsed.error.issues[0]?.message ?? "配音参数无效");
    const result = await audioRequest(credentials, "/audio/speech", parsed.data, options);
    if (!result.ok) return result;
    try {
        const blob = await result.response.blob();
        const mime = blob.type.split(";")[0];
        if (mime === "application/json") {
            const body: unknown = JSON.parse(await blob.text());
            const message = record(body) && record(body.error) ? body.error.message : undefined;
            return failure("provider", typeof message === "string" ? redactCredentials(message, credentials.apiKey).slice(0, 300) : "APIMart 未返回配音文件");
        }
        if (!blob.size || (mime && !mime.startsWith("audio/") && mime !== "application/octet-stream")) return protocol();
        const mimeTypes = {wav: "audio/wav", opus: "audio/ogg", aac: "audio/aac", flac: "audio/flac", pcm: "audio/pcm"};
        return {
            ok: true,
            blob: new Blob([blob], {type: mime?.startsWith("audio/") ? blob.type : mimeTypes[input.response_format]})
        };
    } catch (error) {
        return failure(aborted(error, options.signal) ? "aborted" : "protocol", "未能读取完整的配音文件；不会自动重新生成");
    }
}

export async function submitApimartMusic(credentials: ApimartCredentials, input: MusicInput, options: ApimartRequestOptions = {}): Promise<ApimartResult<{
    taskIds: string[]
}>> {
    const parsed = musicInputSchema.safeParse(input);
    if (!parsed.success) return failure("validation", parsed.error.issues[0]?.message ?? "音乐参数无效");
    const result = await jsonEnvelope(credentials, "/music/generations", parsed.data, options);
    if (!result.ok) return result;
    if (!Array.isArray(result.data) || !result.data.length || !result.data.every(record)) return protocol();
    try {
        return {ok: true, taskIds: canonicalizeAudioTaskIds(result.data.map(row => row.task_id))};
    } catch {
        return protocol();
    }
}

export async function getApimartMusicTask(credentials: ApimartCredentials, taskId: string, options: ApimartRequestOptions = {}): Promise<ApimartResult<{
    task: MusicTask
}>> {
    if (!isAudioTaskId(taskId)) return failure("validation", "音乐任务 ID 无效；请保留任务记录，不要重复提交");
    const result = await jsonEnvelope(credentials, `/music/tasks/${encodeURIComponent(taskId)}?language=zh`, undefined, options);
    if (!result.ok) return result;
    const row = result.data;
    if (!record(row) || row.id !== taskId || !nonempty(row.status)) return protocol();
    const statuses = ["pending", "processing", "completed", "failed"];
    const status = statuses.includes(row.status) ? row.status as MusicTask["status"] : "unknown";
    const tracks: MusicResultTrack[] = [];
    const diagnostics: string[] = [];
    const music = record(row.result) ? row.result.music : undefined;
    if (status === "completed") {
        if (!Array.isArray(music) || !music.length) return protocol();
        for (const [index, track] of music.entries()) {
            if (!record(track) || !safeUrl(track.audio_url)) {
                diagnostics.push(`第 ${index + 1} 首音频缺少有效下载地址`);
                continue;
            }
            const rawDuration = track.duration ?? track.duration_seconds;
            const duration = typeof rawDuration === "string" && rawDuration.trim() ? Number(rawDuration) : rawDuration;
            tracks.push({
                audioIndex: index + 1, audioUrl: track.audio_url,
                title: typeof track.title === "string" ? track.title : `作品 ${index + 1}`,
                ...(nonempty(track.clip_id) ? {clipId: track.clip_id} : {}), ...(nonempty(track.audio_id) ? {audioId: track.audio_id} : {}),
                ...(typeof track.lyrics === "string" ? {lyrics: track.lyrics} : {}),
                ...(finite(duration) && duration > 0 ? {duration} : {}),
                ...(safeUrl(track.wav_url) ? {wavUrl: track.wav_url} : {}), ...(safeUrl(track.image_url) ? {imageUrl: track.image_url} : {}),
            });
        }
    }
    return {
        ok: true, task: {
            id: taskId, status, providerStatus: row.status, tracks,
            ...(finite(row.progress) ? {progress: Math.max(0, Math.min(100, row.progress))} : {}),
            ...(finite(row.cost) ? {cost: row.cost} : {}), ...(finite(row.credits_cost) ? {creditsCost: row.credits_cost} : {}),
            ...(diagnostics.length ? {error: diagnostics.join("；")} : record(row.error) && typeof row.error.message === "string" ? {error: redactCredentials(row.error.message, credentials.apiKey).slice(0, 300)} : {}),
        }
    };
}

/** CDN downloads never receive the connector's bearer token. */
export async function downloadApimartAudio(url: string, options: ApimartRequestOptions = {}): Promise<ApimartResult<{
    blob: Blob
}>> {
    if (!safeUrl(url)) return failure("validation", "音频下载地址无效");
    try {
        const response = await (options.fetchImpl ?? fetch)(url, {
            signal: options.signal,
            credentials: "omit",
            redirect: "error"
        });
        if (!response.ok) return failure("http", `音频下载失败（${response.status}），可以重试下载`);
        const blob = await response.blob();
        if (!blob.size || (blob.type && !blob.type.startsWith("audio/") && blob.type !== "application/octet-stream")) return protocol();
        return {ok: true, blob};
    } catch (error) {
        return failure(aborted(error, options.signal) ? "aborted" : "network", "音频下载未完成，请重试下载；无需重新生成");
    }
}

import {validateAudioTaskObservations} from "./audioGeneration/observations";
import type {AudioTaskObservation} from "@/domain/audioGeneration";
import {z} from "zod";
import {db} from "@/db/database";
import {AUDIO_TABLES} from "@/db/audioShared";
import {
    validateAudioChapter,
    validateAudioClip,
    validateAudioExport,
    validateAudioSegment,
    validateAudioSpeaker,
    validateAudioTake,
    validateAudioTrack
} from "@/db/audio";
import {validateLegacyMusicDraft, validateLegacyMusicWork} from "@/db/music";
import {mimoSpeechSettingsSchema, validateGenerationInput} from "./audioGeneration/input";
import {validateSpeechReference} from "./audioGeneration/reference";
import {createId} from "./ids";
import type {ProjectKind} from "@/domain/types";

const id = z.string().min(1);
const number = z.number().finite();
const base = {id, projectId: id, revision: number.int().positive(), createdAt: z.string(), updatedAt: z.string()};
const meta = {durationSec: number.positive(), sampleRate: number.int().positive(), channels: number.int().positive()};
const provenance = z.object({
    provider: z.enum(["apimart", "mimo"]),
    model: z.string(),
    taskId: z.string().optional(),
    clipId: z.string().optional(),
    audioIndex: number.int().positive().optional(),
    jobId: id.optional(),
    audioUrl: z.string().optional(),
    coverUrl: z.string().optional()
});
const settings = z.discriminatedUnion("engine", [
    z.object({
        engine: z.literal("flowmusic"),
        soundPrompt: z.string(),
        lyrics: z.string(),
        title: z.string(),
        bpm: z.string().optional(),
        lengthSec: number.optional(),
        seed: z.string().optional()
    }),
    z.object({
        engine: z.literal("suno"),
        version: z.enum(["v6", "v6-wild", "v6-mini"]),
        custom: z.boolean(),
        instrumental: z.boolean(),
        prompt: z.string(),
        title: z.string(),
        style: z.string(),
        negativeTags: z.string(),
        durationSec: number.optional()
    }),
]);
const input = z.discriminatedUnion("kind", [
    z.object({
        kind: z.literal("speech"),
        text: z.string(),
        voice: z.string(),
        speed: number,
        mimo: mimoSpeechSettingsSchema.optional(),
        segmentId: id.optional(),
        segmentRevision: number.optional()
    }),
    z.object({kind: z.literal("music"), settings, draftId: id.optional(), draftRevision: number.optional()}),
]);
/** Explicit allowlist: credentials, chat permission data and live claims cannot travel. */
const schemas = {
    audioChapters: z.object({...base, title: z.string(), order: number}),
    audioSpeakers: z.object({
        ...base,
        name: z.string(),
        voice: z.string().optional(),
        speed: number.optional(),
        mimo: mimoSpeechSettingsSchema.optional()
    }),
    audioSegments: z.object({
        ...base,
        chapterId: id,
        speakerId: id.optional(),
        order: number,
        text: z.string(),
        notes: z.string(),
        selectedTakeId: id.optional()
    }),
    audioTakes: z.object({
        ...base, ...meta,
        segmentId: id.optional(),
        mediaId: id,
        name: z.string(),
        source: z.enum(["recording", "upload", "library", "tts", "music"]),
        textSnapshot: z.string().optional(),
        provenance: provenance.optional()
    }),
    audioTracks: z.object({
        ...base,
        chapterId: id,
        role: z.enum(["voice", "music", "effects"]),
        name: z.string(),
        order: number,
        gain: number,
        muted: z.boolean(),
        solo: z.boolean()
    }),
    audioClips: z.object({
        ...base,
        chapterId: id,
        trackId: id,
        takeId: id,
        startSec: number,
        trimStartSec: number,
        trimEndSec: number,
        gain: number,
        fadeInSec: number,
        fadeOutSec: number
    }),
    audioExports: z.object({
        ...base,
        chapterId: id.optional(),
        scope: z.enum(["chapter", "project"]).optional(),
        chapterTitle: z.string().optional(),
        fingerprint: z.string(),
        format: z.literal("wav"),
        mediaId: id,
        durationSec: number
    }),
    musicDrafts: z.object({...base, settings}),
    musicWorks: z.object({
        ...base, ...meta,
        mediaId: id,
        title: z.string(),
        notes: z.string(),
        favorite: z.boolean(),
        lyrics: z.string(),
        settings: settings.optional(),
        provenance: provenance.optional()
    }),
    audioGenerationJobs: z.object({
        ...base,
        intentId: id,
        input,
        connector: z.object({id, provider: z.enum(["apimart", "mimo"]), baseUrl: z.string()}),
        source: z.object({kind: z.literal("manual")}),
        status: z.enum(["prepared", "submitting", "uncertain", "submitted", "running", "remote-completed", "downloading", "saved", "failed", "target-conflict"]),
        taskIds: z.array(z.string()),
        taskObservations: z.custom<AudioTaskObservation[]>().optional(),
        results: z.array(z.object({
            key: id,
            provenance,
            title: z.string(),
            lyrics: z.string().optional(),
            finalTextPreview: z.string().optional(),
            durationSec: number.optional(),
            mediaId: id.optional(),
            takeId: id.optional(),
            workId: id.optional(),
            deleted: z.boolean().optional(),
            error: z.string().optional()
        })),
        error: z.string().optional(),
        dormant: z.literal(true)
    }),
};
type TableName = keyof typeof schemas;
const schema = z.object({
    version: z.literal(1),
    audioChapters: z.array(schemas.audioChapters),
    audioSpeakers: z.array(schemas.audioSpeakers),
    audioSegments: z.array(schemas.audioSegments),
    audioTakes: z.array(schemas.audioTakes),
    audioTracks: z.array(schemas.audioTracks),
    audioClips: z.array(schemas.audioClips),
    audioExports: z.array(schemas.audioExports),
    musicDrafts: z.array(schemas.musicDrafts),
    musicWorks: z.array(schemas.musicWorks),
    audioGenerationJobs: z.array(schemas.audioGenerationJobs),
});
export type AudioPackage = z.infer<typeof schema>;

export async function snapshotAudioPackage(projectId: string): Promise<AudioPackage> {
    const entries = await Promise.all(AUDIO_TABLES.map(async (table) => [table.name, await table.where("projectId").equals(projectId).toArray()]));
    const raw = Object.fromEntries(entries);
    raw.audioGenerationJobs = (await db.audioGenerationJobs.where("projectId").equals(projectId).toArray()).map((job) => ({
        ...job,
        source: {kind: "manual"},
        dormant: true,
        claim: undefined
    }));
    const value = schema.parse({version: 1, ...raw});
    for (const job of value.audioGenerationJobs) validateAudioTaskObservations(job.taskObservations, job.taskIds);
    return value;
}

export function parseAudioPackage(raw: unknown, projectId: unknown, kind: ProjectKind): AudioPackage | undefined {
    if (raw === undefined) {
        if (kind !== "video") throw new Error("缺少音频或音乐项目数据");
        return undefined;
    }
    const value = schema.parse(raw);
    for (const job of value.audioGenerationJobs) validateAudioTaskObservations(job.taskObservations, job.taskIds);
    const seen = new Set<string>();
    for (const name of Object.keys(schemas) as TableName[]) for (const row of value[name]) {
        if (row.projectId !== projectId || seen.has(row.id)) throw new Error("音频项目记录重复或所有者不匹配");
        seen.add(row.id);
        if (kind === "video" || (kind === "music" && name.startsWith("audio") && name !== "audioGenerationJobs") || (kind === "audio" && name.startsWith("music"))) throw new Error("项目包包含其他类型的数据");
    }
    if (kind === "audio" && !value.audioChapters.length) throw new Error("音频项目至少需要一个章节");
    return value;
}

export function remapAudioPackage(value: AudioPackage | undefined, projectId: string, mediaMap: Map<string, string>): AudioPackage | undefined {
    if (!value) return undefined;
    const map = new Map<string, string>();
    for (const name of Object.keys(schemas) as TableName[]) for (const row of value[name]) map.set(row.id, createId("aud"));
    const reference = (id: string) => {
        const next = map.get(id);
        if (!next) throw new Error("音频项目引用的记录缺失");
        return next;
    };
    const media = (id: string) => {
        const next = mediaMap.get(id);
        if (!next) throw new Error("音频项目引用的文件缺失");
        return next;
    };
    const next = structuredClone(value);
    for (const name of Object.keys(schemas) as TableName[]) for (const row of next[name]) {
        row.id = reference(row.id);
        row.projectId = projectId;
        if ("chapterId" in row && row.chapterId) row.chapterId = reference(row.chapterId);
        if ("speakerId" in row && row.speakerId) row.speakerId = reference(row.speakerId);
        if ("segmentId" in row && row.segmentId) row.segmentId = reference(row.segmentId);
        if ("selectedTakeId" in row && row.selectedTakeId) row.selectedTakeId = reference(row.selectedTakeId);
        if ("trackId" in row) row.trackId = reference(row.trackId);
        if ("takeId" in row) row.takeId = reference(row.takeId);
        if ("mediaId" in row) row.mediaId = media(row.mediaId);
        if ("mimo" in row && row.mimo?.referenceMediaId) row.mimo.referenceMediaId = media(row.mimo.referenceMediaId);
        if ("provenance" in row && row.provenance?.jobId) row.provenance.jobId = map.get(row.provenance.jobId);
    }
    for (const job of next.audioGenerationJobs) {
        job.intentId = createId("imported");
        job.connector = {id: "imported", provider: job.connector.provider, baseUrl: ""};
        job.source = {kind: "manual"};
        job.dormant = true;
        if (job.input.kind === "speech" && job.input.mimo?.referenceMediaId) job.input.mimo.referenceMediaId = media(job.input.mimo.referenceMediaId);
        if (job.input.kind === "speech" && job.input.segmentId) job.input.segmentId = map.get(job.input.segmentId);
        if (job.input.kind === "music" && job.input.draftId) job.input.draftId = map.get(job.input.draftId);
        for (const result of job.results) {
            if (result.mediaId) result.mediaId = media(result.mediaId);
            if (result.takeId) result.takeId = map.get(result.takeId);
            if (result.workId) result.workId = map.get(result.workId);
            if (result.provenance.jobId) result.provenance.jobId = map.get(result.provenance.jobId);
        }
    }
    return next;
}

/** Called within the package transaction, after project/media insertion. */
export async function insertAudioPackage(value: AudioPackage | undefined): Promise<void> {
    if (!value) return;
    await db.audioChapters.bulkAdd(value.audioChapters);
    await db.audioSpeakers.bulkAdd(value.audioSpeakers);
    await db.audioSegments.bulkAdd(value.audioSegments);
    await db.audioTakes.bulkAdd(value.audioTakes);
    await db.audioTracks.bulkAdd(value.audioTracks);
    await db.audioClips.bulkAdd(value.audioClips);
    await db.audioExports.bulkAdd(value.audioExports);
    await db.musicDrafts.bulkAdd(value.musicDrafts);
    await db.musicWorks.bulkAdd(value.musicWorks);
    await db.audioGenerationJobs.bulkAdd(value.audioGenerationJobs);
    for (const row of value.audioChapters) await validateAudioChapter(row);
    for (const row of value.audioSpeakers) await validateAudioSpeaker(row);
    for (const row of value.audioSegments) await validateAudioSegment(row);
    for (const row of value.audioTakes) await validateAudioTake(row);
    for (const row of value.audioTracks) await validateAudioTrack(row);
    for (const row of value.audioClips) await validateAudioClip(row);
    for (const row of value.audioExports) await validateAudioExport(row);
    for (const row of value.musicDrafts) await validateLegacyMusicDraft(row);
    for (const row of value.musicWorks) await validateLegacyMusicWork(row);
    for (const job of value.audioGenerationJobs) {
        if (job.input.kind === "speech") {
            if (Boolean(job.input.mimo) !== (job.connector.provider === "mimo")) throw new Error("配音设置与服务商不匹配");
            if (job.input.mimo) validateGenerationInput(job.input);
            await validateSpeechReference(job.projectId, job.input);
        } else if (job.connector.provider !== "apimart") throw new Error("音乐生成服务商无效");
        for (const result of job.results) {
            if (result.mediaId && (await db.media.get(result.mediaId))?.projectId !== job.projectId) throw new Error("生成结果媒体归属无效");
            if (result.takeId && (await db.audioTakes.get(result.takeId))?.projectId !== job.projectId) throw new Error("生成结果配音归属无效");
            if (result.workId && (await db.musicWorks.get(result.workId))?.projectId !== job.projectId) throw new Error("生成结果作品归属无效");
        }
    }
}

import {useRef, useState} from "react";
import {Sparkles} from "lucide-react";
import {db} from "@/db/database";
import {patchMusicDraft} from "@/db/music";
import type {MusicDraft, MusicSettings} from "@/domain/music";
import {prepareAudioGeneration, submitAudioGeneration} from "@/lib/audioGeneration/runtime";
import {flushPendingDrafts, useDebouncedDraft} from "@/lib/debouncedDraft";
import {DraftConflictError} from "@/lib/draftConflict";
import {Checkbox} from "@/components/ui/checkbox";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import {Textarea} from "@/components/ui/textarea";
import {DraftStatus} from "@/components/ui/draft-status";
import {Tabs, TabsList, TabsTrigger} from "@/components/ui/tabs";
import {Disclosure, DisclosureTitle, SelectOption, WorkspaceSelect} from "@/components/audioMusic/controls";
import {ConnectionSelect, errorText, Field} from "@/components/audioMusic/shared";
import {musicVariant, type MusicVariant} from "./draftVariants";

export function MusicCreation({
                                  record,
                                  switching,
                                  changeVariant,
                                  connectorId,
                                  setConnectorId,
                                  onSubmitted,
                                  onSubmittingChange
                              }: {
    record: MusicDraft;
    switching: boolean;
    changeVariant: (target: MusicVariant) => void;
    connectorId: string;
    setConnectorId: (id: string) => void;
    onSubmitted: () => void;
    onSubmittingChange: (value: boolean) => void;
}) {
    const [busy, setBusy] = useState(false);
    const pending = useRef(false);
    const [error, setError] = useState("");
    const {draft, setDraft, status, error: saveError, retry, useLatest} = useDebouncedDraft<MusicSettings>({
        scope: record.projectId, draftKey: `${record.id}:settings`, initialValue: record.settings,
        persist: async (settings, baseline) => {
            const current = await db.musicDrafts.get(record.id);
            if (!current || JSON.stringify(current.settings) !== JSON.stringify(baseline)) throw new DraftConflictError();
            await patchMusicDraft(record.projectId, current.id, current.revision, {settings});
        },
    });
    const update = (patch: Partial<MusicSettings>) => setDraft((previous) => ({...previous, ...patch} as MusicSettings));

    async function generate() {
        if (pending.current) return;
        pending.current = true;
        setBusy(true);
        onSubmittingChange(true);
        setError("");
        try {
            await flushPendingDrafts(record.projectId);
            const current = await db.musicDrafts.get(record.id);
            if (!current) throw new Error("创作草稿不存在");
            const job = await prepareAudioGeneration({
                projectId: record.projectId,
                connectorId,
                input: {kind: "music", settings: current.settings, draftId: current.id, draftRevision: current.revision}
            });
            await submitAudioGeneration(record.projectId, job.id);
            onSubmitted();
        } catch (e) {
            setError(errorText(e));
        } finally {
            pending.current = false;
            setBusy(false);
            onSubmittingChange(false);
        }
    }

    return <div className="mw-creation">
        <div className="mw-compose-scroll">
            <div className="mw-mode-bar">
                {draft.engine === "suno" ? <Tabs value={musicVariant(draft)}
                                                 onValueChange={(value) => changeVariant(value as MusicVariant)}><TabsList
                        aria-label="创作模式"><TabsTrigger disabled={switching || busy}
                                                           value="suno-simple">简单</TabsTrigger><TabsTrigger
                        disabled={switching || busy} value="suno-custom">自定义</TabsTrigger></TabsList></Tabs> :
                    <span className="text-sm font-medium">Flow Music</span>}
                <WorkspaceSelect aria-label="音乐引擎与模型" disabled={switching || busy}
                                 value={draft.engine === "suno" ? draft.version : "flowmusic"}
                                 onValueChange={(value) => {
                                     if (value === "flowmusic") changeVariant("flowmusic");
                                     else if (draft.engine === "suno") update({version: value as "v6" | "v6-mini" | "v6-wild"});
                                     else changeVariant("suno-simple");
                                 }}>{draft.engine === "suno" ? <><SelectOption value="v6">Suno
                        v6</SelectOption><SelectOption value="v6-wild">Suno v6-wild</SelectOption><SelectOption
                        value="v6-mini">Suno v6-mini</SelectOption></> :
                    <SelectOption value="suno">Suno</SelectOption>}<SelectOption value="flowmusic">Flow
                    Music</SelectOption></WorkspaceSelect>
            </div>
            {draft.engine === "suno" ? <>
                <SimpleMusicDurationRepair settings={draft} busy={busy} switching={switching}
                                           onClear={() => update({durationSec: undefined})}/>
                {draft.custom && draft.instrumental ?
                    <p className="mw-instrumental-note">已填写的歌词会保留，切回歌曲后可继续编辑。用下方风格描述这首纯音乐。</p> :
                    <Field label={draft.custom ? "歌词" : "描述你想听到的音乐"}><Textarea disabled={busy || switching}
                                                                                          className="mw-main-input"
                                                                                          rows={draft.custom ? 9 : 7}
                                                                                          aria-label={draft.custom ? "歌词" : "音乐描述"}
                                                                                          maxLength={draft.custom ? 5000 : 3000}
                                                                                          value={draft.prompt}
                                                                                          onChange={(e) => update({prompt: e.target.value})}
                                                                                          placeholder={draft.custom ? "[Verse]\n写下第一句歌词…\n\n[Chorus]\n让旋律记住这一刻" : "午后公路上的独立流行，温暖的吉他，轻快而自在。\n\n写下场景、情绪，或一个灵感。"}/></Field>}
                <label className="mw-check"><Checkbox disabled={busy || switching} checked={draft.instrumental}
                                                      onCheckedChange={(value) => update({instrumental: value === true})}/>纯音乐<span>不含人声</span></label>
                {draft.custom &&
                    <Field label="风格"><Textarea disabled={busy || switching} aria-label="音乐风格" rows={3}
                                                  maxLength={1000} value={draft.style}
                                                  onChange={(e) => update({style: e.target.value})}
                                                  placeholder="独立流行、木吉他、温暖的女声…"/></Field>}
                <Disclosure><DisclosureTitle>更多设置</DisclosureTitle><Field
                    label={draft.custom ? "作品名称（可选）" : "草稿名称（可选）"}><Input disabled={busy || switching}
                                                                                      aria-label={draft.custom ? "作品名称" : "草稿名称"}
                                                                                      value={draft.title} maxLength={80}
                                                                                      onChange={(e) => update({title: e.target.value})}/></Field>{draft.custom && <>
                    <Field label="避免的风格"><Input disabled={busy || switching} aria-label="避免的风格"
                                                     value={draft.negativeTags}
                                                     onChange={(e) => update({negativeTags: e.target.value})}/></Field><Field
                    label="期望时长（秒）"><Input disabled={busy || switching} aria-label="期望时长" type="number"
                                                min={10} max={360} value={draft.durationSec ?? ""}
                                                onChange={(e) => update({durationSec: e.target.value ? Number(e.target.value) : undefined})}/><small>留空自动决定；可填写
                    10–360 秒。</small></Field></>}</Disclosure>
            </> : <>
                <Field label="描述你想听到的音乐"><Textarea disabled={busy || switching} className="mw-main-input"
                                                            aria-label="音乐描述" rows={7} value={draft.soundPrompt}
                                                            onChange={(e) => update({soundPrompt: e.target.value})}
                                                            placeholder="写下风格、情绪、乐器，或让你产生灵感的场景…"/></Field>
                <Disclosure defaultOpen={Boolean(draft.lyrics)}><DisclosureTitle>歌词（可选）</DisclosureTitle><Textarea
                    disabled={busy || switching} aria-label="歌词" rows={7} value={draft.lyrics}
                    onChange={(e) => update({lyrics: e.target.value})} placeholder="写下你的歌词…"/></Disclosure>
                <Disclosure><DisclosureTitle>更多设置</DisclosureTitle><Field label="作品名称（可选）"><Input
                    disabled={busy || switching} aria-label="作品名称" value={draft.title}
                    onChange={(e) => update({title: e.target.value})}/></Field><Field label="期望时长（秒）"><Input
                    disabled={busy || switching} aria-label="期望时长" type="number" min={1} max={240}
                    value={draft.lengthSec ?? ""}
                    onChange={(e) => update({lengthSec: e.target.value ? Number(e.target.value) : undefined})}/></Field><Field
                    label="BPM"><Input disabled={busy || switching} aria-label="BPM" type="number" min={1}
                                       value={draft.bpm ?? ""}
                                       onChange={(e) => update({bpm: e.target.value || undefined})}/></Field><Field
                    label="随机种子"><Input disabled={busy || switching} aria-label="随机种子" value={draft.seed ?? ""}
                                            onChange={(e) => update({seed: e.target.value || undefined})}/></Field></Disclosure>
            </>}
            <DraftStatus status={status} error={saveError} onRetry={() => void retry()} onUseLatest={useLatest}/>
        </div>
        <div className="mw-generate"><ConnectionSelect value={connectorId} onChange={setConnectorId}/><Button
            className="w-full" disabled={!connectorId || busy || switching || status === "error"}
            onClick={() => void generate()}><Sparkles/>{busy ? "提交生成中…" : "生成音乐"}</Button><p>使用所选 APIMart
            账户计费</p>{error && <p role="alert" className="aw-error">{error}</p>}</div>
    </div>;
}

function SimpleMusicDurationRepair({settings, busy, switching, onClear}: {
    settings: MusicSettings;
    busy: boolean;
    switching: boolean;
    onClear: () => void;
}) {
    if (settings.engine !== "suno" || settings.custom || settings.durationSec === undefined) return null;
    return <div className="space-y-2">
        <p className="text-sm text-muted-foreground">此草稿保留了历史时长 {String(settings.durationSec)} 秒；简单模式不支持指定时长。</p>
        <Button type="button" variant="outline" size="sm" disabled={busy || switching}
                onClick={onClear}>清除历史时长</Button>
    </div>;
}
